-- 1. PREPARAÇÃO DO AMBIENTE
DROP DATABASE IF EXISTS magical_bites;
CREATE DATABASE magical_bites;
USE magical_bites;

-- 2. CRIAÇÃO DAS TABELAS
CREATE TABLE categoria (
    id_categoria INT AUTO_INCREMENT PRIMARY KEY,
    nome_categoria VARCHAR(100) NOT NULL
);

CREATE TABLE filme (
    id_filme INT AUTO_INCREMENT PRIMARY KEY,
    nome_filme VARCHAR(255) NOT NULL,
    imagem VARCHAR(255),
    id_categoria INT NOT NULL,
    FOREIGN KEY (id_categoria) REFERENCES categoria(id_categoria)
);
CREATE TABLE receitas (
    id_receita INT AUTO_INCREMENT PRIMARY KEY,
    nome_receita VARCHAR(255) NOT NULL,
    tipo VARCHAR(255) NOT NULL,
    id_filme INT,
    descricao TEXT,
    imagem VARCHAR(255),
    avaliacao DECIMAL(2,1),
    tempo_preparo VARCHAR(50),
    dificuldade VARCHAR(50),
    ingredientes TEXT, 
    modo_preparo TEXT,
    FOREIGN KEY (id_filme) REFERENCES filme(id_filme)
);

-- TABELA DE USUÁRIOS
CREATE TABLE usuario (
    id_usuario INT AUTO_INCREMENT PRIMARY KEY,
    nome_usuario VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL,
    senha VARCHAR(255) NOT NULL,
    foto_perfil VARCHAR(255) DEFAULT 'avatar1.webp'
);

-- TABELA DE AVATARES DISPONÍVEIS NO SISTEMA
CREATE TABLE avatar_predefinido (
    id_avatar INT AUTO_INCREMENT PRIMARY KEY,
    nome_avatar VARCHAR(100) NOT NULL,
    caminho_imagem VARCHAR(255) NOT NULL
);

CREATE TABLE favoritar (
    id_favoritos INT AUTO_INCREMENT PRIMARY KEY,
    id_usuario INT,
    id_receita INT,
    FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario),
    FOREIGN KEY (id_receita) REFERENCES receitas(id_receita)
);

